import os
import torch


class Config:
    # =========================================================================
    # File Paths & Directories
    # =========================================================================
    # Metadata paths (generated by the metadata script)
    TRAIN_DATA_PATH = "./metadata/train.parquet"
    VAL_DATA_PATH = "./metadata/val.parquet"
    TEST_DATA_PATH = "./metadata/test.parquet"

    # Input paths
    SAMPLE_SUBMISSION_PATH = "./input/sample_submission.csv"

    # Working directories (Idea 12 specific)
    WORKING_DIR = "./working/idea_12"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # Ensure working directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(CACHE_DIR, exist_ok=True)

    # =========================================================================
    # Data Configuration
    # =========================================================================
    SEED = 42
    SEQ_LEN = 107
    PRED_LEN = 68

    # Target Columns (Only the 3 scored ones)
    TARGET_COLS = ["reactivity", "deg_Mg_pH10", "deg_Mg_50C"]
    NUM_TARGETS = len(TARGET_COLS)

    # Vocabularies
    # Sequence: A, G, C, U -> 4 tokens + padding if needed (though fixed len)
    VOCAB_SIZE_SEQ = 4
    # Loop Type: S, M, I, B, H, E, X -> 7 tokens
    VOCAB_SIZE_LOOP = 7
    # Bond Types: A-U, U-A, G-C, C-G, G-U, U-G, None -> 7 tokens
    VOCAB_SIZE_BOND = 7

    # =========================================================================
    # Model Architecture (Interaction-Aware Deep Residual BiLSTM)
    # =========================================================================
    # Embedding Dimensions
    EMBED_DIM_SEQ = 32
    EMBED_DIM_LOOP = 32
    EMBED_DIM_DISTANCE = 32  # For Signed Sinusoidal Encoding
    EMBED_DIM_BOND = 32  # For Bond-Type Interaction

    # Total input dimension to the LSTM backbone
    # Sum of all embedding channels
    INPUT_DIM = EMBED_DIM_SEQ + EMBED_DIM_LOOP + EMBED_DIM_DISTANCE + EMBED_DIM_BOND

    # Backbone Configuration
    HIDDEN_DIM = 384  # High capacity as per lesson
    NUM_LAYERS = 5  # Deep network
    DROPOUT = 0.1  # Regularization
    BIDIRECTIONAL = True

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    BATCH_SIZE = 32  # Adjusted for 384 hidden dim on available hardware
    EPOCHS = 50
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-4
    MAX_GRAD_NORM = 1.0

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS  # For CosineAnnealingLR
    ETA_MIN = 1e-6

    # Early Stopping
    PATIENCE = 7

    # Compute
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4
